0	Harry Yee* Took out the above change. The culprit was in All.Macros with the macro* _MidiInputPollVector. It was JSLing to the location $E11dd8, which belongs* to the serial firmware. It now JSLs to $E101B2.** 08 Aug 90	Braz** Changed files StartSound.aii and StartPlaying.aii* to fix problems playing sounds two buffers or less in length* using FFSetUpSound and FFStartPlaying*****************************************************************	Include 'all.macros'	Include 'E16.MIDI'	Include ':::Sound:Snd.Equ.aii';;****************************************************************;; spatch.equ    This module contains all of the equates used by;               the	routines in the sound tools patch file;****************************************************************;		;  MIDI Tool Setsgaddh	equ $C03F	; sound Glu address	high;	export osctable:equosctable	equ $FF40F0	; oscillator xlate table	export gentable:equGentable	equ $FF4100	; generator table.	export gcb_xlate:equgcb_xlate	equ $FF4120	; gen. to gcb entry	addr xlate tableSndEndcall	equ $FF3E54	; EndCall entry point for sound toolsSndOEndcall	equ $FF3E55	; Endcall entry without PLD;;;NewMidiInputPoll	equ $E11DD8;;-----------------------------------------------;;   Forward address	and entries;;-----------------------------------------------******************************************************************* SoundCallTable******************************************************************	EXPORT SoundCallTableSoundCallTable	PROC	Import SoundBootInit	Import st_versin	Import stopsound	Import StartSound	Import SetUpSound	Import StartPlaying	Import SetUpParam	Import ReadParam	Import SoundStartupFunct_1	DC.L num_funct/4	; number of functions	DC.L SoundBootInit-1 ; function 1	DC.L SoundStartup-1	; function 2	DC.L 00000000	; function 3	DC.L st_versin-1	; function 4	DC.L 00000000	; function 5	DC.L 00000000	; function 6	DC.L 00000000	; function 7	DC.L 00000000	; function 8	DC.L 00000000	; function 9	DC.L 00000000	; function A	DC.L 00000000	; function B	DC.L 00000000	; function C	DC.L 00000000	; function D	DC.L StartSound-1	; function E	DC.L stopsound-1	; function F	DC.L 00000000	; function 10	DC.L 00000000	; function 11	DC.L 00000000	; function 12	DC.L 00000000	; function 13	DC.L 00000000	; function 14	DC.L SetUpSound-1	; function 15 	DC.L StartPlaying-1 ; function 16 	DC.L SetUpParam-1	; function 17	DC.L ReadParam-1	; function 18;num_funct	equ *-Funct_1	; number of functions;	ENDP******************************************************************* SoundBootInit** This routine is called by the tool locator when this patch* is installed.** Added 13 Oct 87	 Steven Glass** 13 May 88	Harry Yee and Don Marsh** Added initialization of MidiInputPoll vector.******************************************************************	EXPORT SoundBootInitSoundBootInit	PROC	lda #$6B	; RTL	sta MidiInputPoll		lda #0	clc	rtl	ENDPSoundStartup	PROC			Import Fsynth_irq	tax	; save incoming WAP	lda 7,s	; put input on stack again 	pha	txa	; get it back	jsl callSoundStartUp	pha	; save error code		PushLong #fsynth_irq	; address of sound interrupt handler	_SetSoundMIRQV		plx	; get error code in x	ldy #2	; strip 2	jml ToStrip	callSoundStartUP	jsl $FF3F89	rtl		ENDP			EXPORT st_versinst_versin	PROC****************************************************************** Version number tool returns the current Sound Tool* version #.**    Called:  pea 0	; return value placeholder*             Toolcall 8,4** Returns: X,Y unchanged.  Version on stack******************************************************************;;	longa on	;	longi on	lda #Version_patch	; get vers#	sta $07,s	; place in stack	ldy #0000	; jump to endcall in rom	jmp >SndOEndcall	;;	ENDP;		END